content.content:
.themed-image-background {
	background: var(--surface-subtle);
}

.themed-list-item:hover {
	background: var(--surface-subtle);
}

.btn-background {
	color: var(--button-text-color);
}

p:not(:last-child) {
	margin-bottom: 0.875rem;
}

ol,
ul {
	margin-left: 1rem;
}

ol {
	list-style-type: disc;
}

dt,
dd {
	margin-left: 1em;
	font-size: 20px;
}

.btn-background {
	background: var(--btn-gradient);
}

.bg-gradient {
	background: var(--bg-gradient);
}

.footer-styles {
	background: transparent;
}

.ankor-bg {
	background-color: var(--background-color);
	background-image: var(--anchor-pattern);
}

.ankor-bg-div {
	background: transparent;
	background-image: var(--anchor-pattern);
}

.food_background {
	background: var(--background-color);
	background-image: var(--food-pattern);
}
== landing
12-	flex-direction: column;
13-	align-items: center;
14-	justify-content: center;
15:	background: var(--bg-gradient);
16-}
17-
18-.top_section {
19-	/* Full width and no horizontal margin. As a shrink-to-fit flex item this was
20-	   narrower than every other page's hero column, so the same headline wrapped at
21-	   a different word and the logo rendered smaller here than everywhere else. */
22-	width: 100%;
23-	margin: 2em 0;
24-	display: flex;
25-	flex-direction: column;
26-	align-items: center;
27-	justify-content: center;
== about
3-	flex-direction: column;
4-	align-items: center;
5-	justify-content: center;
6:	background: var(--bg-gradient);
7-	margin-top: var(--nav-offset);
8-}
9-
10-.contact_button {
11-	display: flex;
12-	justify-content: center;
13-	align-self: center;
14-	max-width: 200px;
15-	font-size: 22px;
16-	font-family: "Poppins-Regular", sans-serif;
17-	padding: 0.5em;
18-	margin-bottom: 2em;
== contact
5-	display: flex;
6-	flex-direction: column;
7-	align-items: center;
8:	background: var(--bg-gradient);
9-}
10-
11-.header_1 {
12-	max-width: var(--hero-text-max-width);
13-	margin-inline: auto;
14-	color: var(--font-blue);
15-	text-align: center;
16-	font-size: var(--fs-hero-title);
17-	font-family: "Poppins-Regular", sans-serif;
18-	margin-top: 1em;
19-	margin-bottom: 0.5em;
20-}
== posts
4-	align-items: center;
5-	justify-content: center;
6-	margin-top: var(--nav-offset);
7:	background: var(--bg-gradient);
8-}
9-
10-.image_div {
11-	display: flex;
12-	justify-content: center;
13-	align-content: center;
14-	margin: 1em auto;
15-	width: 100%;
16-	max-width: var(--hero-logo-max-width);
17-	height: var(--hero-logo-height);
18-	position: relative;
