input.function:
async () => {
const main = [...document.querySelectorAll('*')].find(e => getComputedStyle(e).backgroundImage.includes('svg') && getComputedStyle(e).backgroundImage.includes('linear-gradient'));
const r = { injected: !!document.getElementById('sky'), darkAuto: main ? getComputedStyle(main).backgroundImage.slice(-140) : 'none' };
const el = document.querySelector('[class*="landing"]') || main;
document.documentElement.setAttribute('data-theme','light');
r.forcedLight = getComputedStyle(main ?? document.body).backgroundImage.slice(0,140);
document.documentElement.setAttribute('data-theme','dark');
r.forcedDark = getComputedStyle(main).backgroundImage.slice(-90);
document.documentElement.removeAttribute('data-theme');
return r }

