input.command:
python3 - <<'EOF'
import re
def rep(p, old, new, count=1):
    s = open(p).read()
    assert s.count(old) == count, (p, old, s.count(old))
    open(p, 'w').write(s.replace(old, new))

rep('styles/index.css',
'''	--nav-border: 2px solid light-dark(#1b315e, #f4f1e6);
''',
'''	--nav-border: 2px solid light-dark(#1b315e, rgb(196 218 255 / 0.22));
	/* A faint moonlit edge so dark surfaces separate from the night sky. Drawn as
	   a box-shadow ring rather than a border so it takes no layout space, and
	   transparent in light mode, which therefore renders exactly as before. */
	--edge-color: light-dark(transparent, rgb(196 218 255 / 0.18));
	--card-edge: 0 0 0 1px var(--edge-color);
''')

rep('styles/navbar.module.css',
'''		border-top: none;
		box-shadow: none;
''',
'''		border-top: none;
		box-shadow: inset 0 -1px 0 var(--edge-color);
''')

# Cards that sit directly on the sky and have no border of their own.
rep('styles/landing.module.css',
'''	min-height: 500px;
	background: var(--background-color);
	box-shadow: var(--drop-shadow-1);
''',
'''	min-height: 500px;
	background: var(--background-color);
	box-shadow: var(--card-edge), var(--drop-shadow-1);
''')
rep('styles/about.module.css',
'''	border-radius: 10px;
	background: var(--background-color);
	box-shadow: var(--drop-shadow-1);
''',
'''	border-radius: 10px;
	background: var(--background-color);
	box-shadow: var(--card-edge), var(--drop-shadow-1);
''')
rep('styles/about.module.css',
'''	background: var(--background-color);
	box-shadow: var(--card-shadow);
''',
'''	background: var(--background-color);
	box-shadow: var(--card-edge), var(--card-shadow);
''')
rep('styles/contact.module.css',
'''	justify-content: center;
	box-shadow: var(--drop-shadow-1);
}
''',
'''	justify-content: center;
	box-shadow: var(--card-edge), var(--drop-shadow-1);
}
''')
rep('styles/contact.module.css',
'''	max-width: 1000px;
	box-shadow: var(--drop-shadow-1);
	border-radius: 10px;
''',
'''	max-width: 1000px;
	box-shadow: var(--card-edge), var(--drop-shadow-1);
	border-radius: 10px;
''')
EOF
