input.function:
() => {
const q = s => getComputedStyle(document.querySelector(s))
const read = () => ({ card: q('[class*="reach_outer_card"]').boxShadow, nav: q('nav').boxShadow })
const r = { dark: read() }
document.documentElement.setAttribute('data-theme', 'light'); r.light = read()
document.documentElement.removeAttribute('data-theme'); return r }

