() => {
const base = getComputedStyle(document.documentElement).getPropertyValue('--anchor-pattern-dark')
window.__anchor = (fill, op) => {
  let s = document.getElementById('anc'); if (!s) { s = document.createElement('style'); s.id = 'anc'; document.head.append(s) }
  s.textContent = `:root{--anchor-pattern: ${base.replace("%2394d47a", "%23" + fill).replace("fill-opacity='0.35'", `fill-opacity='${op}'`)} !important}
  [class*="landing_container"]{padding-bottom:0 !important}
  .themed-footer{box-shadow: inset 0 1px 0 rgb(196 218 255 / 0.18)}`
}
window.__anchor('7fd8c8', '0.22'); scrollTo(0, document.documentElement.scrollHeight); return base.includes('94d47a') }

