const raw = readFileSync(new URL('./food-groups.json', import.meta.url), 'utf8')
const food = JSON.parse(raw.slice(raw.indexOf('['), raw.lastIndexOf(']') + 1)).map((g) => g.d)
const anchors = [
	'M14 16H9v-2h5V9.87a4 4 0 1 1 2 0V14h5v2h-5v15.95A10 10 0 0 0 23.66 27l-3.46-2 8.2-2.2-2.9 5a12 12 0 0 1-21 0l-2.89-5 8.2 2.2-3.47 2A10 10 0 0 0 14 31.95V16z',
	'M54 56h-5v-2h5v-4.13a4 4 0 1 1 2 0V54h5v2h-5v15.95A10 10 0 0 0 63.66 67l-3.47-2 8.2-2.2-2.88 5a12 12 0 0 1-21.02 0l-2.88-5 8.2 2.2-3.47 2A10 10 0 0 0 54 71.95V56z',
]
const dots = 'M15 62a2 2 0 1 1 0-4 2 2 0 0 1 0 4zm40-40a2 2 0 1 1 0-4 2 2 0 0 1 0 4zM15 8a2 2 0 1 0 0-4 2 2 0 0 0 0 4zm40 40a2 2 0 1 0 0-4 2 2 0 0 0 0 4z'
const grad = (from, to) => `<defs><linearGradient id='g' x1='0.63' y1='0' x2='0.37' y2='1'><stop offset='0' stop-color='${from}'/><stop offset='0.87' stop-color='${to}'/></linearGradient></defs>`
const uri = (svg) => `url("data:image/svg+xml,${svg.replaceAll('<', '%3C').replaceAll('>', '%3E').replaceAll('#', '%23')}")`
export const anchor = ([from, to], op) => uri(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80' width='80' height='80'>${grad(from, to)}<g fill='url(#g)' fill-opacity='${op}'>${anchors.map((d) => `<path d='${d}'/>`).join('')}</g><path fill='${to}' fill-opacity='${+(op * 0.6).toFixed(2)}' d='${dots}'/></svg>`)
export const foodTile = ([from, to], op) => uri(`<svg xmlns='http://www.w3.org/2000/svg' width='260' height='260' viewBox='0 0 260 260'>${grad(from, to)}<g fill='url(#g)' fill-opacity='${op}' fill-rule='evenodd'>${food.map((d) => `<path d='${d}'/>`).join('')}</g></svg>`)
export const LIGHT = ['#00d936', '#0ad9d9']
export const DARK = ['#00b02c', '#06adad']
EOF
