for (const op of [0.35, 0.45, 0.5]) { v[`da${op}`] = anchor(DARK, op); v[`df${op}`] = foodTile(DARK, op) }
writeFileSync('/home/peterc/main-website/public/__pat.json', JSON.stringify(v))
console.log(Object.keys(v).join(' '), v.lf1.length)
EOF
node preview.mjs

