input.function:
async () => {
window.__v = await (await fetch('/__pat.json')).json()
window.__set = (a, f) => { let s = document.getElementById('pat'); if (!s) { s = document.createElement('style'); s.id = 'pat'; document.head.append(s) } s.textContent = `:root{--anchor-pattern:${window.__v[a]} !important;--food-pattern:${window.__v[f]} !important}` }
window.__set('da0.5', 'df0.45'); document.querySelector('[class*="reach_outer_card"]').scrollIntoView({ block: 'start' }); scrollBy(0, -40); return 'ok' }

