file.content:
@font-face {
	font-family: "Open Sans";
	src: url("../public/OpenSans-Regular.ttf") format("ttf");

	font-display: swap;
}

.landing_container {
	margin-top: var(--nav-offset);
	padding: 1em;
	padding-bottom: var(--landing-end-gap, 1em);
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	background: var(--bg-gradient);
}

.top_section {
	/* Full width and no horizontal margin. As a shrink-to-fit flex item this was
	   narrower than every other page's hero column, so the same headline wrapped at
	   a different word and the logo rendered smaller here than everywhere else. */
	width: 100%;
	margin: 2em 0;
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
}

.text {
	color: var(--font-blue);
	font-family: "Open Sans", sans-serif;
}

.top_text {
	margin-top: 2em;
	margin-bottom: 1em;
	color: var(--font-blue);
	font-family: "Poppins-Regular", sans-serif;
}

.h1_text {
	max-width: var(--hero-text-max-width);
	margin-inline: auto;
	font-size: var(--fs-hero-title);
	font-family: "Poppins-Regular", sans-serif;
	text-align: center;
	margin-top: 1em;
	margin-bottom: 0.5em;
	color: var(--font-blue);
}

.h2_text {
	max-width: var(--hero-text-max-width);
	margin-inline: auto;
	font-size: var(--fs-hero-subtitle);
	font-family: "Poppins-Regular", sans-serif;
	text-align: center;
	margin-top: 1em;
	color: var(--font-blue);
}

.image_div {
	display: flex;
	justify-content: center;
	align-content: center;
	margin: 1em auto;
	width: 100%;
	max-width: var(--hero-logo-max-width);
	height: var(--hero-logo-height);
	position: relative;
}

/* Next's fill layout stretches the image to the box unless told otherwise. This
   used to be `object-fit: "contain"` on the box itself — quoted, so invalid, and
   on the wrong element — which left the logo distorted differently per page. */
.image_div img {
	object-fit: contain;
}

.top_link {
	font-family: "Poppins-Regular", sans-serif;
	text-decoration: underline;
	color: var(--font-blue);
	font-size: 22px;
	text-align: center;
}

.text {
	font-size: 18px;
	color: var(--font-blue);
	font-family: "Poppins-Regular", sans-serif;
}

.home_card {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: space-around;
	margin: 2em 2em;
	padding: 1em;
	border-radius: 10px;
	width: 90%;
	max-width: 1000px;
	min-height: 500px;
	background: var(--background-color);
	box-shadow: var(--card-edge), var(--drop-shadow-1);
}

.mission {
	margin-bottom: 1em;
	color: var(--font-blue);
	font-size: var(--fs-section-title);
	font-family: "Poppins-Regular", sans-serif;
}

.about_us {
	margin-top: 3em;
	padding: 0.5em;
	border-radius: 46px;
	border: 1px solid var(--button-border);
	background: var(--btn-gradient);
	box-shadow: var(--drop-shadow-1);
	color: var(--button-text-color);
	font-size: 28px;
	margin-bottom: 1em;
	font-family: "Poppins-Regular", sans-serif;
}

.rounded_image {
	border-radius: 20px;
	overflow: hidden;
}

.volunteer {
	font-family: "Poppins-Regular", sans-serif;
	font-size: var(--fs-section-title);
	color: var(--font-blue);
	text-align: center;
	margin-top: 1em;
	margin-bottom: 1em;
}

.volunteer_text {
	font-family: "Open Sans", sans-serif;
	font-size: 20px;
	color: var(--font-blue);
	text-align: left;
}

.btn_styles {
	border-radius: 46px;
	border: 1px solid var(--button-border);
	background: var(--btn-gradient);
	box-shadow: var(--drop-shadow-1);
	color: var(--button-text-color);
	font-size: 22px;
	margin-top: 3em;
	margin-bottom: 1em;
	padding: 0.5em;
	font-family: "Poppins-Regular", sans-serif;
}

.latest {
	font-size: 20px;
	color: var(--font-blue);
	text-decoration: underline;
	cursor: pointer;
	font-family: "Poppins-Regular", sans-serif;
}

.overview {
	margin: 2em;
}

.about_header {
	font-family: "Poppins-Regular", sans-serif;
	font-size: var(--fs-section-title);
	color: var(--font-blue);
	text-align: center;
	margin-bottom: 1em;
	margin-top: 0.5em;
}

.about_text {
	font-family: "Open Sans", sans-serif;
	font-size: 18px;
	color: var(--font-blue);
	text-align: left;
}

.location {
	display: flex;
	flex-direction: column;
	align-items: center;
	width: 100vw;
	height: auto;
	z-index: 1;
}

.location_header {
	text-align: center;
	margin-top: 4em;
	margin-bottom: 1em;
	font-size: var(--fs-section-title);
	color: var(--font-blue);
	font-family: "Poppins-Regular", sans-serif;
}

.location_image {
	position: relative;
	width: 100%;
	aspect-ratio: 16 / 9;
	border-radius: 10px;
	z-index: 1;
	margin-bottom: 4em;
}

@media (min-width: 768px) {
	.location_image {
		width: 80vw;
	}
}

@media (min-width: 1024px) {
	.location_image {
		width: 70vw;
	}
}

/* media queries */
/* The hero heading and logo sizes are shared tokens now, so this block no longer
