:root[data-theme="dark"] {
	color-scheme: dark;
}

/* light-dark() only accepts colors, so the image swaps (patterns, sky), the
   lengths below and the logo filter still need an explicit dark selector.
   --landing-end-gap: in light mode the home page's bottom padding shows as an
   orange accent stripe above the footer; at night it is just a seam of sky. */
:root[data-theme="dark"] {
	--bg-gradient: var(--bg-gradient-dark);
	--landing-end-gap: 0px;
	--anchor-pattern: var(--anchor-pattern-dark);
	--food-pattern: var(--food-pattern-dark);
}

:root[data-theme="dark"] img[src="/logo.svg"] {
	filter: brightness(0) invert(1) sepia(0.4) opacity(0.94);
}

@media (prefers-color-scheme: dark) {
	:root:not([data-theme="light"]) {
		--bg-gradient: var(--bg-gradient-dark);
		--landing-end-gap: 0px;
		--anchor-pattern: var(--anchor-pattern-dark);
		--food-pattern: var(--food-pattern-dark);
	}

	:root:not([data-theme="light"]) img[src="/logo.svg"] {
		filter: brightness(0) invert(1) sepia(0.4) opacity(0.94);
	}
}

.footer-styles {
	background: transparent;
}

.ankor-bg {
	background-color: var(--background-color);
	background-image: var(--anchor-pattern);
}

.ankor-bg-div {
	background: transparent;
	background-image: var(--anchor-pattern);
}

.food_background {
	background: var(--background-color);
	background-image: var(--food-pattern);
}
		light-dark(rgba(148, 104, 0, 0.2), rgba(0, 0, 0, 0.38));

	/* Anchor and food patterns are filled with the --btn-gradient colours for each
	   mode (195deg), applied per icon so every anchor and food item gets the full
	   sweep and the patterns match the buttons that sit on them. */

