content.content:
.container {
	margin-top: 0;
	min-height: 100vh;
	padding-bottom: 10vh;
	display: flex;
	flex-direction: column;
	align-items: center;
	background: var(--bg-gradient);
}

.header_1 {
	max-width: var(--hero-text-max-width);
	margin-inline: auto;
	color: var(--font-blue);
	text-align: center;
	font-size: var(--fs-hero-title);
	font-family: "Poppins-Regular", sans-serif;
	margin-top: 1em;
	margin-bottom: 0.5em;
}

.header_2 {
	max-width: var(--hero-text-max-width);
	margin-inline: auto;
	margin-top: 1em;
	color: var(--font-blue);
	text-align: center;
	font-family: "Poppins-Regular", sans-serif;
	font-size: var(--fs-hero-subtitle);
}
.about_container {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	background: var(--bg-gradient);
	margin-top: var(--nav-offset);
}

.contact_button {
	display: flex;
	justify-content: center;
.posts_page {
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	margin-top: var(--nav-offset);
	background: var(--bg-gradient);
}

.image_div {
	display: flex;
	justify-content: center;
